package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveEntry;
import org.apache.commons.compress.archivers.zip.ZipArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipException;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_getNextZipEntry_TriageGen1Test {

    private static final long LFH_SIG = 0x04034b50L;
    private static final long CFH_SIG = 0x02014b50L;
    private static final long AED_SIG = 0x06054b50L;

    /**
     * Helper to create a valid LFH buffer for testing
     */
    private byte[] createLFHBuffer(String fileName, int method, boolean hasDataDescriptor) {
        byte[] nameBytes = fileName.getBytes();
        int size = 30; // header size before name and extra
        if (hasDataDescriptor) {
            size += 12; // CRC, compressed, uncompressed
        } else {
            size += 16; // CRC, compressed, uncompressed, plus extra padding logic in code
        }

        // Simplified buffer construction matching the logic in getNextZipEntry
        // LFH_BUF structure: Sig(4), Ver(2), Flags(2), Method(2), Time(4), Date(2), CRC(4), Comp(4), Uncomp(4), NameLen(2), ExtraLen(2)
        int totalSize = 30 + nameBytes.length + 2; // 2 for extra len 0
        ByteBuffer bb = ByteBuffer.allocate(totalSize).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) LFH_SIG);
        bb.putShort((short) 20); // version
        bb.putShort((short) 0);  // flags
        bb.putShort((short) method);
        bb.putInt(0); // time
        bb.putShort((short) 0); // date

        if (!hasDataDescriptor) {
            bb.putInt(123); // crc
            bb.putInt(456); // compressed
            bb.putInt(789); // uncompressed
        } else {
            // The code skips 3 * WORD if hasDataDescriptor is true
            bb.position(bb.position() + 12);
        }

        bb.putShort((short) nameBytes.length);
        bb.putShort((short) 0); // extra len
        bb.put(nameBytes);

        return bb.array();
    }

    @Test
    public void testGetNextZipEntry_ClosedOrHitCentralDirectory() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        // Simulate closed
        zis.close();
        assertNull(zis.getNextZipEntry());

        // Simulate hitCentralDirectory via a fake stream that returns CFH signature
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) CFH_SIG);
        ZipArchiveInputStream zis2 = new ZipArchiveInputStream(new ByteArrayInputStream(bb.array()));
        assertNull(zis2.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_EOF() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);
        assertNull(zis.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_UnexpectedSignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(0xBADBEEF);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(bb.array()));

        try {
            zis.getNextZipEntry();
            fail("Should have thrown ZipException");
        } catch (ZipException e) {
            assertTrue(e.getMessage().contains("Unexpected record signature"));
        }
    }

    @Test
    public void testGetNextZipEntry_SuccessStandard() throws IOException {
        byte[] lfh = createLFHBuffer("test.txt", 0, false); // Method 0 = STORED
        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(lfh));

        ZipArchiveEntry entry = zis.getNextZipEntry();
        assertNotNull(entry);
        assertEquals("test.txt", entry.getName());
        assertEquals(123, entry.getCrc());
    }

    @Test
    public void testGetNextZipEntry_SuccessWithDataDescriptor() throws IOException {
        // Manually construct buffer to trigger hasDataDescriptor branch
        // Flags bit for Data Descriptor is usually bit 3 (0x08)
        ByteBuffer bb = ByteBuffer.allocate(100).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) LFH_SIG);
        bb.putShort((short) 20);
        bb.putShort((short) 0x0008); // Data Descriptor flag
        bb.putShort((short) 8);      // Deflate
        bb.putInt(0);                // Time
        bb.putShort((short) 0);      // Date
        bb.position(bb.position() + 12); // Skip the 3*WORD in the 'else' branch
        bb.putShort((short) 4);      // Name len
        bb.putShort((short) 0);      // Extra len
        bb.put("file".getBytes());

        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(bb.array()));
        ZipArchiveEntry entry = zis.getNextZipEntry();

        assertNotNull(entry);
        assertEquals("file", entry.getName());
    }

    @Test
    public void testGetNextZipEntry_UTF8() throws IOException {
        // Flag bit 8 is UTF-8
        ByteBuffer bb = ByteBuffer.allocate(100).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) LFH_SIG);
        bb.putShort((short) 20);
        bb.putShort((short) 0x0800); // UTF8 flag
        bb.putShort((short) 0);      // Method
        bb.putInt(0);                // Time
        bb.putShort((short) 0);      // Date
        bb.putInt(0);                // CRC
        bb.putInt(0);                // Comp
        bb.putInt(0);                // Uncomp
        bb.putShort((short) 4);      // Name len
        bb.putShort((short) 0);      // Extra len
        bb.put("test".getBytes());

        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(bb.array()));
        ZipArchiveEntry entry = zis.getNextZipEntry();
        assertNotNull(entry);
        assertEquals("test", entry.getName());
    }

    @Test
    public void testGetNextZipEntry_CompressionMethods() throws IOException {
        // Test Deflate (Imploding)
        ByteBuffer bb = ByteBuffer.allocate(100).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) LFH_SIG);
        bb.putShort((short) 20);
        bb.putShort((short) 0);
        bb.putShort((short) 8); // Deflate
        bb.putInt(0);
        bb.putShort((short) 0);
        bb.putInt(0);
        bb.putInt(10); // Compressed size
        bb.putInt(10); // Uncompressed size
        bb.putShort((short) 4);
        bb.putShort((short) 0);
        bb.put("data".getBytes());

        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(bb.array()));
        ZipArchiveEntry entry = zis.getNextZipEntry();
        assertNotNull(entry);
        assertEquals(8, entry.getMethod());
    }
}
